CREATE POLICY "Anyone views product images" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'product-images');
CREATE POLICY "Managers upload product images" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'product-images' AND (storage.foldername(name))[1] ~ '^[0-9a-f-]{36}$' AND (public.is_restaurant_manager(auth.uid(), ((storage.foldername(name))[1])::uuid) OR public.has_role(auth.uid(), 'admin')) AND lower(storage.extension(name)) IN ('jpg','jpeg','png','webp'));
CREATE POLICY "Managers delete product images" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'product-images' AND (storage.foldername(name))[1] ~ '^[0-9a-f-]{36}$' AND (public.is_restaurant_manager(auth.uid(), ((storage.foldername(name))[1])::uuid) OR public.has_role(auth.uid(), 'admin')));